import re

def parse_record(line):
    """Parse a record line into a dict.
    - Fields are separated by ";". Empty fields are ignored.
    - A field is either key=value or a bare key, which maps to True.
    - Keys and unquoted values have surrounding whitespace removed.
    - A value may be wrapped in double quotes: inside the quotes ";" is literal, \\" is an escaped
      quote, and the text is kept exactly (no trimming). The quotes themselves are removed.
    - If a key repeats, the later value wins.

    parse_record('name=Ana; city = Lyon') == {"name": "Ana", "city": "Lyon"}
    parse_record('note="a;b"; urgent') == {"note": "a;b", "urgent": True}
    """
    fields = []
    current = []
    in_quotes = False
    i = 0
    n = len(line)

    while i < n:
        ch = line[i]
        if in_quotes:
            if ch == '\\' and i + 1 < n and line[i + 1] == '"':
                current.append('\\"')
                i += 2
                continue
            elif ch == '"':
                in_quotes = False
                current.append(ch)
            else:
                current.append(ch)
        else:
            if ch == '"':
                in_quotes = True
                current.append(ch)
            elif ch == ';':
                fields.append("".join(current))
                current = []
            else:
                current.append(ch)
        i += 1
    fields.append("".join(current))

    result = {}
    for field in fields:
        if not field.strip():
            continue
        if '=' in field:
            key, val = field.split('=', 1)
            key = key.strip()
            val_stripped = val.strip()
            if len(val_stripped) >= 2 and val_stripped.startswith('"') and val_stripped.endswith('"'):
                inner = val_stripped[1:-1]
                inner = inner.replace('\\"', '"')
                result[key] = inner
            else:
                result[key] = val_stripped
        else:
            key = field.strip()
            result[key] = True

    return result

